#define R2D(a) mat2(cos(a + vec4(0,11,33,0)))

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float i,j,d=.1,e=1.;
    vec3 p;
    fragColor=vec4(0.);

    for(i=0.;i++<64.&&d>1e-4;){
        p=vec3((fragCoord.xy-.5*iResolution.xy)/iResolution.y,1);
        p.xz*=R2D(1.57);
        p.yz*=R2D(iTime);

        for(j=0.;j++<12.;)
            p.yz*=R2D(1.96),
            p=abs(abs(p))-.05,
            d=min(max(p.z,p.y),p.x)/d;
            d-=dot(p,p)/1e4;

        e-=d;

    }fragColor += vec4(sqrt(-p),1)*8./i;
}
